import java.util.Iterator;
import sailpoint.object.AuditEvent;
import sailpoint.object.ProvisioningPlan.AccountRequest;
import sailpoint.object.ProvisioningResult;
import sailpoint.server.Auditor;

if (plan == null || plan.getAccountRequests() == null) {
    return;
}
for (Iterator it = plan.getAccountRequests().iterator(); it.hasNext();) {
    AccountRequest req = (AccountRequest) it.next();
    if (!application.getName().equals(req.getApplication())) {
        continue;
    }
    ProvisioningResult r = req.getResult() != null ? req.getResult() : result;
    AuditEvent ev = new AuditEvent();
    ev.setAction("fsgovProvisioning");
    ev.setSource("FSGov-AfterProvisioning");
    ev.setApplication(application.getName());
    ev.setAccountName(req.getNativeIdentity());
    ev.setTarget(plan.getIdentity() != null ? plan.getIdentity().getName() : req.getNativeIdentity());
    if (r != null) {
        ev.setAttribute("status", r.getStatus());
        ev.setAttribute("fsgovChangePlan", r.getAttribute("fsgovChangePlan"));
        ev.setAttribute("fsgovPlanDigest", r.getAttribute("fsgovPlanDigest"));
        ev.setAttribute("fsgovWarnings", r.getAttribute("fsgovWarnings"));
    }
    Auditor.log(ev);
}
context.commitTransaction();
